package com.anssa8bu.ssafy.common.redis; import org.junit.jupiter.api.Test; import java.time.*; import static org.assertj.core.api.Assertions.*; class RedisTtlPropertiesTest { @Test void capsSessionAtExpiry(){var p=new RedisTtlProperties(Duration.ofDays(30),Duration.ofSeconds(60),Duration.ofSeconds(60),Duration.ofMinutes(10),Duration.ofSeconds(45),Duration.ofMinutes(10),Duration.ofMinutes(10),Duration.ofMinutes(1));Clock c=Clock.fixed(Instant.EPOCH,ZoneOffset.UTC);assertThat(p.sessionUntil(Instant.EPOCH.plusSeconds(30),c)).isEqualTo(Duration.ofSeconds(30));assertThatThrownBy(()->p.sessionUntil(Instant.EPOCH,c)).isInstanceOf(IllegalArgumentException.class);}}
